60:       if(!['READY','RETRYABLE'].includes(current.state))return {state:current,result:{skip:current.state}};
61:       const refusal=ownerPublicationRefusal(current.analysis);
62:       if(refusal&&current.analysis?.kind!=='DELIVERY_DIAGNOSTIC'){current.state='SUPPRESSED';current.reason=refusal;current.updated_ts=now;return {state:current,result:{skip:'SUPPRESSED',reason:refusal}};}
63:       if(current.expires_ts<=now||current.mode==='AUTO'&&!automaticWindowOpen(now)){current.state='STALE';current.updated_ts=now;return {state:current,result:{skip:'STALE'}};}
64:       if((current.retry_after_ts??0)>now)return {state:current,result:{skip:'BACKOFF'}};
65:       current.state='SENDING';current.owner=owner;current.claim_until=now+claim_ms;current.send_started_ts=null;current.attempts++;
66:       return {state:current,result:structuredClone(current)};
67:     });
68:     if(card.skip)return {state:card.skip,card_id,...(card.reason?{reason:card.reason}:{})};

